        </button>
        {save.isError && <span data-testid="note-error">A note needs text, and only a steward or clerk may add one.</span>}
      </form>
      <ul>
        {(notes.data ?? []).map((n) => (
          <li key={n.id} data-testid="note-line">{`${n.addedOn} ${n.by}: ${n.text}`}</li>
        ))}
      </ul>
    </section>
  );
}
